const tabId = 248688717;

const reviews = await browserjs(tabId, () => {
  // Let's find each review container.
  // In the new Steam UI or standard layout, each review card has distinct structure.
  // Let's look for elements that have author, recommendation, playtime, and body.
  const cards = Array.from(document.querySelectorAll('div, button, a')).filter(el => {
    return el.innerText && 
      el.innerText.includes('hrs on record') && 
      (el.innerText.includes('Recommended') || el.innerText.includes('Not Recommended')) &&
      el.innerText.includes('POSTED:');
  });

  // Filter to only top-level cards (not ancestors or descendants)
  // An element is top-level if no other element in the list is an ancestor of it, or find the most specific one.
  // Actually, let's find elements whose direct text or immediate structure represents one review.
  const results = [];

  // Let's look for the buttons/divs we saw earlier, e.g. where ref was e21152 etc.
  // In DOM:
  for (const c of cards) {
    // Check if this card contains another card
    const hasChildCard = cards.some(other => other !== c && c.contains(other));
    if (!hasChildCard) {
      results.push(c.innerText);
    }
  }

  return results;
});

console.log("Found specific review cards count:", reviews.length);
reviews.slice(0, 10).forEach((r, idx) => {
  console.log(`--- REVIEW ${idx + 1} ---`);
  console.log(r);
});

